// снимки app/S-17-mincha-p1.txt (кнопки шапки y=74 h=44 → центр 96 pt, «1 מתוך 8», «יחיד»/«מניין»), S-33-after-switch*.png
// («4 מתוך 8 נפילת אפים» → «6 מתוך 11 נפילת אפים», «מנחה (ספרדי)»), S-21-explain-mincha.txt, S-22-finish.txt, S-23-after-finish.txt.
// RD-02a — iOS-калиброванный сквозной вариант GP-01/PM-01/NS-02/GP-02 (те написаны по web-локаторам: «מנחה (אשכנזי)» текстом,
// а на iPhone заголовок — кнопка «בחירת נוסח. הנוסח המוצג: X»). Кейсы: .qa/tests/readiness/RD-02-prayer.md.
import { expect, driver, $$ } from '@wdio/globals';
import { byText, byTextContains, byLabel, pageCounter, tapText, scrollToText } from '../../helpers/ui.ts';
import { skipWith, shown, ensureNusach } from '../_lib/app-0710.ts';
import {
  goHome, openCatalogPrayer, counterNM, goPage, headerTap, shownNusach, button, tapFinish, recordAllowed,
  FINISH_TITLE, BACK_HOME, visibleActionButtons, counter, labelOf,
} from '../_lib/readiness-1910.ts';

/** Режим «יחיד»/«מניין» выбран? (iOS: value/selected у элемента Other; Android: selected/checked). */
async function modeSelected(name: 'יחיד' | 'מניין') {
  const el = await byLabel(name);
  await el.waitForExist({ timeout: 15000 });
  if (driver.isAndroid) return (await el.getAttribute('selected')) === 'true' || (await el.getAttribute('checked')) === 'true';
  const v = String((await el.getAttribute('value').catch(() => '')) ?? '');
  return v === '1' || v === 'true' || (await el.isSelected().catch(() => false)) || String(await el.getAttribute('traits').catch(() => '')).includes('Selected');
}

describe('Готовность 19.10 — молитва', () => {
  afterEach(async () => { await goHome().catch(() => {}); });

  it('RD-02a מנחה: «X מתוך N», «יחיד» по умолчанию, «הסבר על התפילה», смена נוסח на «4 מתוך 8» → «(ספרדי)» «6 מתוך 11» «נפילת אפיים», выход и возврат на ту же часть #6a86f7e9 #6a86f7e7 #6a86f7fdaa68 F-96 F-103 F-37 F-42 @prod-safe', async () => {
    await openCatalogPrayer('מנחה');
    await ensureNusach('אשכנזי');
    expect(await shownNusach()).toBe('אשכנזי');
    const [, total] = await counterNM();
    expect(total).toBeGreaterThan(1);                         // факт 19.10: 8
    expect(await modeSelected('יחיד')).toBe(true);           // F-103 AC4
    expect(await modeSelected('מניין')).toBe(false);

    // F-42: ⓘ «הסבר על התפילה» → «על תפילת מנחה» + «💡 טיפ» → ✕ «סגירה» → та же часть.
    await goPage(4);
    expect(await pageCounter()).toBe(`4 מתוך ${total}`);
    await expect(byTextContains('נפילת אפים')).toBeExisting();
    await headerTap('הסבר על התפילה');
    await expect(byTextContains('על תפילת מנחה')).toBeDisplayed({ wait: 15000 });
    await expect(byTextContains('טיפ')).toBeDisplayed();
    await (await button('סגירה')).click();
    await expect(byTextContains('על תפילת מנחה')).not.toBeDisplayed({ wait: 10000 });
    expect(await pageCounter()).toBe(`4 מתוך ${total}`);

    // F-37: смена נוסח в молитве — параллельная часть и шапка «(ספרדי)».
    await ensureNusach('ספרדי');
    expect(await shownNusach()).toBe('ספרדי');
    const [n2, t2] = await counterNM();
    console.log(`[RD-02a] после смены: ${n2} מתוך ${t2}`);
    expect(t2).not.toBe(total);                                // 8 → 11 (19.10)
    await expect(byTextContains('נפילת אפיים')).toBeExisting();

    // F-96 AC2: «חזרה» (шапка, по имени) → снова открыть → та же часть.
    await headerTap('חזרה');
    await openCatalogPrayer('מנחה');
    await ensureNusach('ספרדי');
    expect(await pageCounter()).toBe(`${n2} מתוך ${t2}`);
    await ensureNusach('אשכנזי');                              // уборка: нусах в молитве назад
  });

  it('RD-02b Завершение без нового достижения: окно «כל הכבוד!» «סיימת את תפילת <X> בהצלחה» с ОДНОЙ кнопкой «חזרה למסך ראשי» → главная; «תפילה ראשונה» не повторяется #6a86f7e9 F-41 AC4 F-90 AC1 @data', async function () {
    if (!recordAllowed()) skipWith(this, 'добавляет запись молитвы (необратимо) — запуск с QA_RECORD_PRAYER=1 на тестовом аккаунте');
    await goHome();
    if ((await counter('סה״כ תפילות')) === 0) skipWith(this, 'первая молитва аккаунта даёт достижение «תפילה ראשונה» — нужен аккаунт с 1+ молитвой');
    let finished: string | null = null;
    for (const p of ['ערבית', 'מנחה', 'שחרית']) {
      await openCatalogPrayer(p);
      const r = await tapFinish();
      if (r === 'already') { await (await button('ביטול')).click(); continue; }
      finished = p;
      break;
    }
    if (!finished) skipWith(this, 'все три молитвы уже записаны сегодня — повторить завтра');
    await expect(byTextContains(`סיימת את תפילת ${finished} בהצלחה`)).toBeDisplayed();
    const btns = await visibleActionButtons([BACK_HOME, 'המשך']);
    console.log(`[RD-02b] ${finished}: кнопки окна — ${btns.join(', ')}`);
    if (btns.includes('המשך')) {
      // Следом окно достижения/уровня (не случай AC4). Проверяем F-90 AC1 и не засчитываем AC4.
      await (await button('המשך')).click();
      await (await button(BACK_HOME)).waitForExist({ timeout: 15000 });
      expect(await shown(byText('תפילה ראשונה'))).toBe(false);
      await (await button(BACK_HOME)).click();
      skipWith(this, 'после этой молитвы выдано достижение/уровень — AC4 (окно без достижения) не проверен, повторить другой молитвой');
    }
    expect(btns).toEqual([BACK_HOME]);
    expect(await shown(byText('תפילה ראשונה'))).toBe(false);
    await (await button(BACK_HOME)).click();
    await expect(byText(FINISH_TITLE)).not.toBeDisplayed({ wait: 10000 });
    await (await button('התחל תפילה')).waitForExist({ timeout: 20000 });

    // F-90 AC1: в «המסע שלי» «תפילה ראשונה: הושג» ровно одно.
    await tapText('המסע שלי');
    await scrollToText('הישגים');
    const items = await $$(driver.isAndroid
      ? 'android=new UiSelector().descriptionStartsWith("תפילה ראשונה:")'
      : '-ios predicate string:label BEGINSWITH "תפילה ראשונה:"');
    const labels: string[] = [];
    for (const it of items) labels.push(await labelOf(it as unknown as WebdriverIO.Element));
    expect(labels).toEqual(['תפילה ראשונה: הושג']);
  });
});
